import { test, expect } from '@playwright/test';

test.describe('Mobile Hamburger Menu Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/mobile-menu');
  });

  test('should open and close the hamburger menu correctly on mobile viewport', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 862 });

    // Verify menu button is visible
    const menuButton = page.getByRole('button', { name: /menu/i });
    await expect(menuButton).toBeVisible();

    // Click to open menu
    await menuButton.click();

    // Verify menu is open and visible
    const navMenu = page.getByRole('navigation');
    await expect(navMenu).toBeVisible();

    // Verify menu items are visible
    const homeLink = page.getByRole('link', { name: /home/i });
    await expect(homeLink).toBeVisible();

    const aboutLink = page.getByRole('link', { name: /about/i });
    await expect(aboutLink).toBeVisible();

    // Verify close button is visible
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Click close button
    await closeButton.click();

    // Verify menu is closed
    await expect(navMenu).not.toBeVisible();
  });

  test('should handle menu interaction and close when clicking outside', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 860 });

    // Open menu
    const menuButton = page.getByRole('button', { name: /menu/i });
    await menuButton.click();

    const navMenu = page.getByRole('navigation');
    await expect(navMenu).toBeVisible();

    // Click outside the menu to close it
    const body = page.locator('body');
    await body.click();

    // Verify menu is closed
    await expect(navMenu).not.toBeVisible();

    // Open menu again
    await menuButton.click();
    await expect(navMenu).toBeVisible();

    // Verify menu items are still accessible
    const contactLink = page.getByRole('link', { name: /contact/i });
    await expect(contactLink).toBeVisible();

    // Click on a menu item to navigate
    await contactLink.click();

    // Verify navigation occurred
    await expect(page).toHaveURL(/contact/);
  });
});
